"""JSON Schema generation and strict argument parsing for tool argument dataclasses."""

import json
from collections.abc import Callable, Mapping
from dataclasses import Field, dataclass, fields
from enum import StrEnum
from typing import Any, get_type_hints

from support_agent.domain.decisions import ReasonCode

MINIMUM_KEY = "minimum"
JSON_TYPE_NAMES: Mapping[type, str] = {str: "string", int: "integer"}


@dataclass(frozen=True)
class ToolFault:
    reason: ReasonCode
    detail: str


class _InvalidValue(ValueError):
    pass


def _is_enum(field_type: object) -> bool:
    return isinstance(field_type, type) and issubclass(field_type, StrEnum)


def _fields_of(arguments_type: type[Any]) -> tuple[Field[Any], ...]:
    return fields(arguments_type)


def _property(field_type: type[Any], field: Field[Any]) -> dict[str, object]:
    if _is_enum(field_type):
        return {"type": "string", "enum": [member.value for member in field_type]}
    prop: dict[str, object] = {"type": JSON_TYPE_NAMES[field_type]}
    prop.update(field.metadata)
    return prop


def schema_for(arguments_type: type[Any]) -> dict[str, object]:
    hints = get_type_hints(arguments_type)
    members = _fields_of(arguments_type)
    return {
        "type": "object",
        "properties": {f.name: _property(hints[f.name], f) for f in members},
        "required": [f.name for f in members],
        "additionalProperties": False,
    }


def _coerce(field_type: type[Any], field: Field[Any], value: object) -> object:
    if _is_enum(field_type):
        try:
            return field_type(value)
        except ValueError:
            raise _InvalidValue(f"{field.name}: not one of the allowed values") from None
    if field_type is int:
        if isinstance(value, bool) or not isinstance(value, int):
            raise _InvalidValue(f"{field.name}: must be an integer")
        if value < field.metadata.get(MINIMUM_KEY, value):
            raise _InvalidValue(f"{field.name}: must be at least {field.metadata[MINIMUM_KEY]}")
        return value
    if not isinstance(value, str):
        raise _InvalidValue(f"{field.name}: must be a string")
    return value


def _invalid(detail: str) -> ToolFault:
    return ToolFault(ReasonCode.INVALID_ARGUMENTS, detail)


def _field_values(arguments_type: type[Any], raw: Mapping[str, object]) -> dict[str, object]:
    hints = get_type_hints(arguments_type)
    return {f.name: _coerce(hints[f.name], f, raw[f.name]) for f in _fields_of(arguments_type)}


def parse_arguments[T](arguments_type: type[T], arguments_json: str) -> T | ToolFault:
    try:
        raw = json.loads(arguments_json)
    except ValueError:
        return _invalid("arguments are not valid JSON")
    if not isinstance(raw, dict):
        return _invalid("arguments must be a JSON object")
    names = {f.name for f in _fields_of(arguments_type)}
    if missing := names - raw.keys():
        return _invalid(f"missing fields: {', '.join(sorted(missing))}")
    if extra := raw.keys() - names:
        return _invalid(f"unexpected fields: {', '.join(sorted(extra))}")
    factory: Callable[..., T] = arguments_type
    try:
        return factory(**_field_values(arguments_type, raw))
    except _InvalidValue as error:
        return _invalid(str(error))
EOF
