"""Money amounts a customer wrote in a message; claims are compared with records, never paid."""

import re
from decimal import Decimal

from support_agent.domain.money import Currency, Money

ID_TOKEN_PATTERN = re.compile(r"\b[A-Z]{2,5}-[A-Z0-9-]*\d[A-Z0-9-]*\b")
MONEY_PATTERN = re.compile(r"(?<![\w.,-])(?:€\s?)?(\d+[.,]\d{2})(?![\w-]|[.,]\d)(?:\s?EUR\b)?", re.IGNORECASE)


def strip_id_tokens(message: str) -> str:
    return ID_TOKEN_PATTERN.sub(" ", message)


def extract_claimed_amounts(message: str, currency: Currency) -> tuple[Money, ...]:
    return tuple(
        Money(Decimal(match.group(1).replace(",", ".")), currency)
        for match in MONEY_PATTERN.finditer(strip_id_tokens(message))
    )
EOF

