cat > src/support_agent/application/tools.py <<'EOF'
"""Tool commands and their registry; no tool can move money, request_refund only proposes."""

from collections.abc import Callable, Mapping
from dataclasses import dataclass, field
from typing import Any

from support_agent.application.model_protocol import ToolCall, ToolSchema
from support_agent.application.ports import CustomerOrders, CustomerRefunds
from support_agent.application.tool_schema import ToolFault, parse_arguments, schema_for
from support_agent.domain.decisions import Decision, DecisionKind, ReasonCode
from support_agent.domain.ids import CustomerId, ItemId, OrderId
from support_agent.domain.money import Money
from support_agent.domain.orders import Order, OrderLine
from support_agent.domain.refunds import RefundReason
from support_agent.domain.turn import ProposedRefund
from support_agent.policy.engine import PolicyEngine, RefundAssessment
from support_agent.policy.refund_amounts import idempotency_key, refunded_quantity
from support_agent.policy.rules import RefundCheck

__all__ = ["ToolFault", "ToolOutcome", "ToolRegistry", "TurnContext"]

LIST_MY_ORDERS = "list_my_orders"
GET_ORDER = "get_order"
REQUEST_REFUND = "request_refund"
ESCALATE_TO_HUMAN = "escalate_to_human"


@dataclass(frozen=True)
class TurnContext:
    customer_id: CustomerId
    orders: CustomerOrders
    refunds: CustomerRefunds
    claimed_amounts: tuple[Money, ...]


@dataclass(frozen=True)
class ToolOutcome:
    result: Mapping[str, object]
    decision: Decision | None = None
    proposal: ProposedRefund | None = None
    escalation_reasons: tuple[ReasonCode, ...] = ()


@dataclass(frozen=True)
class NoArguments:
    pass


@dataclass(frozen=True)
class GetOrderArguments:
    order_id: str


@dataclass(frozen=True)
class RequestRefundArguments:
    order_id: str
    item_id: str
    quantity: int = field(metadata={"minimum": 1})
    reason: RefundReason


@dataclass(frozen=True)
class Command[A]:
    name: str
    description: str
    arguments_type: type[A]
    handler: Callable[[A, TurnContext], ToolOutcome]


def _line_view(line: OrderLine, refunded: int) -> dict[str, object]:
    return {
        "item_id": line.item_id,
        "name": line.name,
        "quantity": line.quantity,
        "unit_price": str(line.unit_price.amount),
        "refunded_quantity": refunded,
    }


def _order_view(order: Order, context: TurnContext) -> dict[str, object]:
    records = context.refunds.for_order(order.order_id)
    shipping = order.shipping
    return {
        "found": True,
        "order_id": order.order_id,
        "status": order.status.value,
        "currency": order.total.currency.value,
        "total": str(order.total.amount),
        "shipping": None if shipping is None else {"carrier": shipping.carrier, "tracking_number": shipping.tracking_number},
        "lines": [_line_view(line, refunded_quantity(line.item_id, records)) for line in order.lines],
    }


def _list_my_orders(_: NoArguments, context: TurnContext) -> ToolOutcome:
    orders = [{"order_id": order.order_id, "status": order.status.value} for order in context.orders.list_orders()]
    return ToolOutcome(result={"orders": orders})


def _get_order(arguments: GetOrderArguments, context: TurnContext) -> ToolOutcome:
    order = context.orders.find_order(OrderId(arguments.order_id))
    return ToolOutcome(result={"found": False} if order is None else _order_view(order, context))


def _escalate_to_human(_: NoArguments, __: TurnContext) -> ToolOutcome:
    decision = Decision(DecisionKind.ESCALATE, ReasonCode.CUSTOMER_REQUESTED_HUMAN)
    return ToolOutcome(
        result={"escalated": True},
        decision=decision,
        escalation_reasons=(ReasonCode.CUSTOMER_REQUESTED_HUMAN,),
    )


def _escalation_reasons(assessment: RefundAssessment) -> tuple[ReasonCode, ...]:
    reasons: list[ReasonCode] = []
    if assessment.decision.kind is DecisionKind.ESCALATE:
        reasons.append(assessment.decision.reason)
    if assessment.dispute is not None:
        reasons.append(ReasonCode.AMOUNT_DISPUTE)
    return tuple(dict.fromkeys(reasons))


def _refund_result(
    assessment: RefundAssessment, order: Order | None, arguments: RequestRefundArguments
) -> dict[str, object]:
    decision = assessment.decision
    result: dict[str, object] = {"decision": decision.kind.value, "reason_code": decision.reason.value}
    line = None if order is None else order.line(ItemId(arguments.item_id))
    if decision.amount is not None and line is not None:
        result.update(amount=decision.amount.format(), item_name=line.name, quantity=arguments.quantity)
    if assessment.dispute is not None:
        result["amount_dispute"] = True
    return result


def _proposal(
    decision: Decision, order: Order | None, arguments: RequestRefundArguments, context: TurnContext
) -> ProposedRefund | None:
    line = None if order is None else order.line(ItemId(arguments.item_id))
    if order is None or line is None or decision.amount is None:
        return None
    if decision.kind is not DecisionKind.NEEDS_CONFIRMATION:
        return None
    already = refunded_quantity(line.item_id, context.refunds.for_order(order.order_id))
    key = idempotency_key(context.customer_id, order.order_id, line.item_id, arguments.quantity, already)
    return ProposedRefund(
        order_id=order.order_id,
        item_id=line.item_id,
        item_name=line.name,
        quantity=arguments.quantity,
        amount=decision.amount,
        reason=arguments.reason,
        idempotency_key=key,
    )


class ToolRegistry:
    def __init__(self, engine: PolicyEngine) -> None:
        self._engine = engine
        commands: tuple[Command[Any], ...] = (
            Command(LIST_MY_ORDERS, "List the customer's own orders with their status.", NoArguments, _list_my_orders),
            Command(GET_ORDER, "Look up one of the customer's orders by order ID.", GetOrderArguments, _get_order),
            Command(
                REQUEST_REFUND,
                "Ask for a refund of an item on an order. Only proposes; the customer must confirm.",
                RequestRefundArguments,
                self._request_refund,
            ),
            Command(
                ESCALATE_TO_HUMAN,
                "Hand the conversation to a human agent when the customer asks for a person.",
                NoArguments,
                _escalate_to_human,
            ),
        )
        self._commands: dict[str, Command[Any]] = {command.name: command for command in commands}

    def schemas(self) -> tuple[ToolSchema, ...]:
        return tuple(
            ToolSchema(command.name, command.description, schema_for(command.arguments_type))
            for command in self._commands.values()
        )

    def run(self, call: ToolCall, context: TurnContext) -> ToolOutcome | ToolFault:
        command = self._commands.get(call.name)
        if command is None:
            return ToolFault(ReasonCode.UNKNOWN_TOOL, f"unknown tool: {call.name}")
        arguments = parse_arguments(command.arguments_type, call.arguments_json)
        if isinstance(arguments, ToolFault):
            return arguments
        outcome: ToolOutcome = command.handler(arguments, context)
        return outcome

    def _request_refund(self, arguments: RequestRefundArguments, context: TurnContext) -> ToolOutcome:
        order_id = OrderId(arguments.order_id)
        order = context.orders.find_order(order_id)
        check = RefundCheck(
            order=order,
            item_id=ItemId(arguments.item_id),
            quantity=arguments.quantity,
            claimed_amounts=context.claimed_amounts,
            order_refunds=context.refunds.for_order(order_id),
            customer_refunds=context.refunds.all(),
        )
        assessment = self._engine.assess_refund(check)
        return ToolOutcome(
            result=_refund_result(assessment, order, arguments),
            decision=assessment.decision,
            proposal=_proposal(assessment.decision, order, arguments, context),
            escalation_reasons=_escalation_reasons(assessment),
        )
EOF

