"""Deterministic stand-in for a language model: keyword intents, generic entity patterns, no store access."""

import json
import re
from dataclasses import dataclass
from enum import StrEnum

from support_agent.application.claims import MONEY_PATTERN, strip_id_tokens
from support_agent.application.model_protocol import Message, ModelRequest, ModelResponse, Role, ToolCall
from support_agent.domain.decisions import DecisionKind, ReasonCode
from support_agent.domain.refunds import RefundReason

ORDER_ID_PATTERN = re.compile(r"\b[A-Z]{2,5}-\d+\b")
QUANTITY_PATTERN = re.compile(r"\b(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\b")
WORD_PATTERN = re.compile(r"[a-z]+")
NUMBER_WORDS = ("one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten")
MIN_TOKEN_LENGTH = 3


class Intent(StrEnum):
    HUMAN = "human"
    REFUND = "refund"
    STATUS = "status"
    UNCLEAR = "unclear"


INTENT_KEYWORDS: tuple[tuple[Intent, re.Pattern[str]], ...] = (
    (Intent.HUMAN, re.compile(r"\b(?:human|person|agent|manager)")),
    (Intent.REFUND, re.compile(r"\b(?:refund|money back|reimburse)")),
    (Intent.STATUS, re.compile(r"\b(?:where|status|track|arrive|delivered)")),
)
DAMAGED_PATTERN = re.compile(r"\b(?:broken|damaged|cracked)")
RETURNED_PATTERN = re.compile(r"\breturn")

GET_ORDER = "get_order"
REQUEST_REFUND = "request_refund"
ESCALATE_TO_HUMAN = "escalate_to_human"

CLARIFY_ORDER = "Which order do you mean? Please send me exactly one order ID."
CLARIFY_ITEM = "Which item from the order is this about?"
CLARIFY_QUANTITY = "How many of that item would you like a refund for?"
CLARIFY_REQUEST = "I can check an order, look into a refund or pass you to a colleague. What would you like?"
NOT_FOUND_REPLY = "I can't find order {order_id} on your account."
STATUS_REPLY = "Order {order_id} is {status}."
SHIPPING_REPLY = " It ships with {carrier}, tracking number {tracking_number}."
NO_ESTIMATE_REPLY = " I don't have a delivery estimate on file."
OFFER_REPLY = "I can offer a refund for {quantity} × {item_name} from order {order_id}."
ESCALATED_REPLY = "This needs a review by a colleague; I've passed it on."
FALLBACK_REPLY = "I couldn't complete that request."
DENY_REPLIES: dict[str, str] = {
    ReasonCode.ORDER_NOT_FOUND: "I can't find that order on your account.",
    ReasonCode.ORDER_NOT_ELIGIBLE: "That order isn't eligible for a refund at the moment.",
    ReasonCode.ITEM_NOT_ON_ORDER: "That item isn't on this order.",
    ReasonCode.ALREADY_REFUNDED: "That item has already been refunded.",
    ReasonCode.QUANTITY_EXCEEDS_REFUNDABLE: "That's more units than can still be refunded.",
    ReasonCode.EXCEEDS_AMOUNT_PAID: "That refund would be more than was paid for the order.",
}


@dataclass(frozen=True)
class _Turn:
    text: str
    results: dict[str, dict[str, object]]
    tool_messages: int


def _as_dict(value: object) -> dict[str, object]:
    return {str(k): v for k, v in value.items()} if isinstance(value, dict) else {}


def _payload(message: Message) -> dict[str, object]:
    try:
        return _as_dict(_as_dict(json.loads(message.content)).get("untrusted_data"))
    except ValueError:
        return {}


def _read_turn(messages: tuple[Message, ...]) -> _Turn:
    start = max((i for i, m in enumerate(messages) if m.role is Role.USER), default=0)
    turn = messages[start:]
    names = {call.call_id: call.name for m in turn for call in m.tool_calls}
    results = {names[m.tool_call_id]: _payload(m) for m in turn if m.role is Role.TOOL and m.tool_call_id in names}
    text = turn[0].content if turn else ""
    return _Turn(text, results, sum(1 for m in turn if m.role is Role.TOOL))


def _normalise(text: str) -> str:
    return MONEY_PATTERN.sub(" ", strip_id_tokens(text)).lower()


def detect_intent(normalised: str) -> Intent:
    return next((intent for intent, pattern in INTENT_KEYWORDS if pattern.search(normalised)), Intent.UNCLEAR)


def detect_reason(normalised: str) -> RefundReason:
    if DAMAGED_PATTERN.search(normalised):
        return RefundReason.DAMAGED
    return RefundReason.RETURNED if RETURNED_PATTERN.search(normalised) else RefundReason.OTHER


def detect_quantity(normalised: str) -> int | None:
    for token in QUANTITY_PATTERN.findall(normalised):
        value = NUMBER_WORDS.index(token) + 1 if token in NUMBER_WORDS else int(token)
        if value >= 1:
            return value
    return None


def _stem(token: str) -> str:
    if token.endswith("es"):
        return token[:-2]
    return token[:-1] if token.endswith("s") else token


def _name_matches(name: str, normalised: str) -> bool:
    stems = (_stem(token) for token in WORD_PATTERN.findall(name.lower()))
    return any(len(stem) >= MIN_TOKEN_LENGTH and stem in normalised for stem in stems)


def _lines(order: dict[str, object]) -> list[dict[str, object]]:
    lines = order.get("lines")
    return [_as_dict(line) for line in lines] if isinstance(lines, list) else []


def select_line(order: dict[str, object], normalised: str) -> dict[str, object] | None:
    lines = _lines(order)
    if len(lines) == 1:
        return lines[0]
    matches = [line for line in lines if _name_matches(str(line.get("name", "")), normalised)]
    return matches[0] if len(matches) == 1 else None


def _call(turn: _Turn, name: str, arguments: dict[str, object]) -> ModelResponse:
    call = ToolCall(f"call-{turn.tool_messages + 1}", name, json.dumps(arguments))
    return ModelResponse(text=None, tool_calls=(call,))


def _say(text: str) -> ModelResponse:
    return ModelResponse(text=text)


def _status_reply(order_id: str, order: dict[str, object]) -> str:
    reply = STATUS_REPLY.format(order_id=order_id, status=str(order.get("status", "unknown")).replace("_", " "))
    shipping = _as_dict(order.get("shipping"))
    if shipping:
        reply += SHIPPING_REPLY.format(
            carrier=shipping.get("carrier", ""), tracking_number=shipping.get("tracking_number", "")
        )
    return reply + NO_ESTIMATE_REPLY


def _refund_reply(order_id: str, result: dict[str, object]) -> str:
    kind = result.get("decision")
    if kind == DecisionKind.NEEDS_CONFIRMATION:
        return OFFER_REPLY.format(
            quantity=result.get("quantity", ""), item_name=result.get("item_name", ""), order_id=order_id
        )
    if kind == DecisionKind.ESCALATE:
        return ESCALATED_REPLY
    if kind == DecisionKind.DENY:
        return DENY_REPLIES.get(str(result.get("reason_code")), FALLBACK_REPLY)
    return FALLBACK_REPLY


class HeuristicModel:
    """ModelClient that reads only the latest user message and this turn's tool results."""

    def complete(self, request: ModelRequest) -> ModelResponse:
        turn = _read_turn(request.messages)
        normalised = _normalise(turn.text)
        intent = detect_intent(normalised)
        if intent is Intent.HUMAN:
            return self._human(turn)
        if intent is Intent.UNCLEAR:
            return _say(CLARIFY_REQUEST)
        order_ids = ORDER_ID_PATTERN.findall(turn.text)
        if len(order_ids) != 1:
            return _say(CLARIFY_ORDER)
        if intent is Intent.STATUS:
            return self._status(turn, order_ids[0])
        return self._refund(turn, order_ids[0], normalised)

    def _human(self, turn: _Turn) -> ModelResponse:
        if ESCALATE_TO_HUMAN in turn.results:
            return _say(ESCALATED_REPLY)
        return _call(turn, ESCALATE_TO_HUMAN, {})

    def _status(self, turn: _Turn, order_id: str) -> ModelResponse:
        order = turn.results.get(GET_ORDER)
        if order is None:
            return _call(turn, GET_ORDER, {"order_id": order_id})
        if not order.get("found"):
            return _say(NOT_FOUND_REPLY.format(order_id=order_id))
        return _say(_status_reply(order_id, order))

    def _refund(self, turn: _Turn, order_id: str, normalised: str) -> ModelResponse:
        order = turn.results.get(GET_ORDER)
        if order is None:
            return _call(turn, GET_ORDER, {"order_id": order_id})
        if not order.get("found"):
            return _say(NOT_FOUND_REPLY.format(order_id=order_id))
        result = turn.results.get(REQUEST_REFUND)
        if result is not None:
            return _say(_refund_reply(order_id, result))
        return self._propose(turn, order_id, order, normalised)

    def _propose(self, turn: _Turn, order_id: str, order: dict[str, object], normalised: str) -> ModelResponse:
        line = select_line(order, normalised)
        if line is None:
            return _say(CLARIFY_ITEM)
        quantity = detect_quantity(normalised)
        if quantity is None and line.get("quantity") == 1:
            quantity = 1
        if quantity is None:
            return _say(CLARIFY_QUANTITY)
        arguments: dict[str, object] = {
