VALID = '{"label": "x", "count": 2, "colour": "red"}'


def test_schema_shape() -> None:
    assert schema_for(Sample) == {
        "type": "object",
        "properties": {
            "label": {"type": "string"},
            "count": {"type": "integer", "minimum": 1},
            "colour": {"type": "string", "enum": ["red", "blue"]},
        },
        "required": ["label", "count", "colour"],
        "additionalProperties": False,
    }


def test_schema_for_no_arguments() -> None:
    assert schema_for(Empty) == {
        "type": "object",
        "properties": {},
        "required": [],
        "additionalProperties": False,
    }


def test_valid_arguments_parse() -> None:
    assert parse_arguments(Sample, VALID) == Sample("x", 2, Colour.RED)


def test_empty_object_parses_for_no_arguments() -> None:
    assert parse_arguments(Empty, "{}") == Empty()


